            printf("rxdataF[%d] is not allocated.\n", i);
            continue;
        }

        int total_elements = NUMBER_RX_BUFFERS * ru->fp->symbols_per_slot * ru->fp->ofdm_symbol_size;
        printf("--- rxdataF[%d] ---\n", i);

        for (int j = 0; j < total_elements; j++) {
            // Print each element. Adjust format as needed.
