Here's an example of handling a blocking read interrupted by a signal with proper EINTR handling:

```c
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <string.h>

void sigint_handler(int sig) {
    /* Signal handler writes directly to stderr using async-safe write */
    const char *msg = "SIGINT received (this is non-fatal)\n";
    write(STDERR_FILENO, msg, strlen(msg));
}

int main() {
    struct sigaction sa;
    char buf[1024];
    ssize_t n;

    /* Configure SIGINT handler */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;  // Important: Don't use SA_RESTART

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    printf("Type a message (press Ctrl+C to test interruption)...\n");

    while (1) {
        /* This read can be interrupted by SIGINT */
        n = read(STDIN_FILENO, buf, sizeof(buf));

        if (n == -1) {
            if (errno == EINTR) {
                /* Signal interrupted our read - just restart it */
                printf("-> Read interrupted, restarting...\n");
                continue;
            }
            perror("read");
            return 1;
        }
        else if (n == 0) {
            printf("EOF reached\n");
            break;
        }
        else {
            /* Successful read - show input and exit */
            printf("Received %zd bytes: %.*s", n, (int)n, buf);
            break;
        }
    }

    return 0;
}
```

Key points:

1. **Signal Handler Setup**:
   - Uses `sigaction()` instead of `signal()` for better control
   - Explicitly *doesn't* use `SA_RESTART` flag to allow EINTR
   - Handler uses `write()` (async-safe) instead of `printf()`

2. **EINTR Handling**:
   - After each interrupted system call, checks for `errno == EINTR`
   - Restarts the read operation when interrupted
   - Handles other errors appropriately

3. **Behavior**:
   - Try pressing Ctrl+C while the program is waiting for input
   - The read will restart after each interruption
   - The program only exits when it receives valid input or EOF

To test:
1. Compile with `gcc -o eintr_example eintr_example.c`
2. Run `./eintr_example`
3. Press Ctrl+C multiple times while it's waiting for input
4. Type a message and press Enter to see it displayed

This shows the proper pattern for handling interrupted system calls in POSIX-compliant systems.

Here's a C++ code example that reads UDP packets from a socket on port 888:

```cpp
#include <iostream>
#include <cstring>
#include <cerrno>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

int main() {
    // Create UDP socket
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        std::cerr << "Socket creation failed: " << strerror(errno) << std::endl;
        return EXIT_FAILURE;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        std::cerr << "setsockopt failed: " << strerror(errno) << std::endl;
        close(sockfd);
        return EXIT_FAILURE;
    }

    // Configure server address
    struct sockaddr_in servaddr{};
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(888);

    // Bind the socket
    if (bind(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        std::cerr << "Bind failed: " << strerror(errno) << std::endl;
        close(sockfd);
        return EXIT_FAILURE;
    }

    std::cout << "Listening for UDP packets on port 888..." << std::endl;

    char buffer[65507]; // Maximum UDP packet size
    struct sockaddr_in cliaddr{};
    socklen_t len = sizeof(cliaddr);

    while (true) {
        // Receive packet
        ssize_t packet_size = recvfrom(sockfd, buffer, sizeof(buffer), 0,
                                      (struct sockaddr*)&cliaddr, &len);
        if (packet_size < 0) {
            std::cerr << "recvfrom error: " << strerror(errno) << std::endl;
            continue;
        }

        // Get client information
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &cliaddr.sin_addr, client_ip, sizeof(client_ip));
        unsigned short client_port = ntohs(cliaddr.sin_port);

        // Print packet information
        std::cout << "Received " << packet_size << " bytes from "
                  << client_ip << ":" << client_port << std::endl;

        // Print packet content as hexadecimal
        std::cout << "Packet data (hex): ";
        for (ssize_t i = 0; i < packet_size; ++i) {
            printf("%02x ", static_cast<unsigned char>(buffer[i]));
        }
        std::cout << "\n" << std::endl;
    }

    close(sockfd);
    return EXIT_SUCCESS;
}
```

This code:

1. Creates a UDP socket (SOCK_DGRAM)
2. Sets SO_REUSEADDR option to allow quick port reuse
3. Binds to all available interfaces (INADDR_ANY) on port 888
4. Continuously receives packets using recvfrom()
5. Prints sender information and packet contents in hexadecimal

Key features:
- Handles maximum UDP packet size (65,507 bytes)
- Shows sender IP address and port
- Displays packet content in hex format
- Includes error checking for socket operations

