# Terrain.gd
class_name Terrain
extends Node3D

const CHUNK_SIZE = 16
const RENDER_DISTANCE = 8

var noise = FastNoiseLite.new()
var chunks = {}
var player_last_chunk = Vector3.INF

@onready var player = get_node("../Player")

func _ready():
    noise.seed = randi()
    noise.frequency = 0.01
    generate_world()

func _process(_delta):
    var player_chunk = get_chunk_position(player.global_position)
    if player_chunk != player_last_chunk:
        update_chunks(player_chunk)
        player_last_chunk = player_chunk

func get_chunk_position(world_pos: Vector3) -> Vector3:
    return Vector3(
        floor(world_pos.x / CHUNK_SIZE),
        0,
        floor(world_pos.z / CHUNK_SIZE)
    )

func update_chunks(center_chunk: Vector3):
    var chunks_to_keep = {}

    for x in range(center_chunk.x - RENDER_DISTANCE, center_chunk.x + RENDER_DISTANCE):
        for z in range(center_chunk.z - RENDER_DISTANCE, center_chunk.z + RENDER_DISTANCE):
            var chunk_pos = Vector3(x, 0, z)
            if not chunks.has(chunk_pos):
                generate_chunk(chunk_pos)
            chunks_to_keep[chunk_pos] = true

    # Remove old chunks
    for chunk_pos in chunks.keys():
        if not chunks_to_keep.has(chunk_pos):
            remove_chunk(chunk_pos)

func generate_chunk(position: Vector3):
    var chunk = Chunk.new(position)
    add_child(chunk)
    chunks[position] = chunk

    # Generate terrain
    for x in Chunk.CHUNK_SIZE:
        for z in Chunk.CHUNK_SIZE:
            var world_x = position.x * CHUNK_SIZE + x
            var world_z = position.z * CHUNK_SIZE + z
            var height = noise.get_noise_2d(world_x, world_z) * 32 + 64

            for y in Chunk.CHUNK_HEIGHT:
                if y > height:
                    continue
                var block_type = Block.BlockType.STONE
                if y == floor(height):
                    block_type = Block.BlockType.GRASS
                elif y > floor(height) - 4:
                    block_type = Block.BlockType.DIRT
                chunk.set_block(x, y, z, block_type)

    chunk.generate_mesh()

func remove_chunk(position: Vector3):
    if chunks.has(position):
        chunks[position].queue_free()
        chunks.erase(position)
