        val bufferSize = AudioRecord.getMinBufferSize(
            sampleRate,
            AudioFormat.CHANNEL_IN_MONO,
            AudioFormat.ENCODING_PCM_16BIT
        )

        val audioRecord = AudioRecord(
            MediaRecorder.AudioSource.MIC,
            sampleRate,
            AudioFormat.CHANNEL_IN_MONO,
            AudioFormat.ENCODING_PCM_16BIT,
            bufferSize
        )

        val audioTrack = AudioTrack(
            AudioManager.STREAM_MUSIC,
            sampleRate,
            AudioFormat.CHANNEL_OUT_MONO,
            AudioFormat.ENCODING_PCM_16BIT,
            bufferSize,
            AudioTrack.MODE_STREAM
        )

        audioRecord.startRecording()
        audioTrack.play()

        val buffer = ShortArray(bufferSize / 2)
        Thread {
            while (isRecording) {
                val read = audioRecord.read(buffer, 0, buffer.size)
                if (read > 0) {
                    val processed = processNativeReverb(nativeHandle, buffer)
                    audioTrack.write(processed, 0, processed.size)
                }
            }

            audioRecord.stop()
            audioTrack.stop()
            releaseNativeReverb(nativeHandle)
        }.start()
    }

    private external fun initNativeReverb(): Long
    private external fun processNativeReverb(handle: Long, input: ShortArray): ShortArray
    private external fun releaseNativeReverb(handle: Long)
}
