**2. C++ JNI Code (Reverb processing):**

```cpp
#include <jni.h>
#include <cmath>
#include <cstring>

class CombFilter {
public:
    CombFilter(size_t delay, float feedback) 
        : delay(delay), feedback(feedback), buffer(new float[delay]()), index(0) {}

    ~CombFilter() { delete[] buffer; }

    float process(float input) {
        float output = buffer[index];
        buffer[index] = input + output * feedback;
        index = (index + 1) % delay;
        return output;
    }

private:
    size_t delay;
    float feedback;
    float* buffer;
    size_t index;
};

class AllPassFilter {
public:
    AllPassFilter(size_t delay, float feedback)
        : delay(delay), feedback(feedback), buffer(new float[delay]()), index(0) {}

    ~AllPassFilter() { delete[] buffer; }

    float process(float input) {
        float buffered = buffer[index];
        float output = -input + buffered;
        buffer[index] = input + buffered * feedback;
        index = (index + 1) % delay;
        return output;
    }

private:
    size_t delay;
    float feedback;
    float* buffer;
    size_t index;
};

class ReverbEffect {
public:
    ReverbEffect(int sampleRate) {
        combs[0] = new CombFilter(static_cast<size_t>(0.05 * sampleRate), 0.7f);
        combs[1] = new CombFilter(static_cast<size_t>(0.056 * sampleRate), 0.7f);
        combs[2] = new CombFilter(static_cast<size_t>(0.061 * sampleRate), 0.7f);
        combs[3] = new CombFilter(static_cast<size_t>(0.068 * sampleRate), 0.7f);

        allPasses[0] = new AllPassFilter(static_cast<size_t>(0.01 * sampleRate), 0.5f);
        allPasses[1] = new AllPassFilter(static_cast<size_t>(0.025 * sampleRate), 0.5f);
    }

    ~ReverbEffect() {
        for (auto& comb : combs) delete comb;
        for (auto& ap : allPasses) delete ap;
    }

    void process(short* input, short* output, int numSamples) {
        const float wet = 0.5f;
        const float dry = 1.0f - wet;

        for (int i = 0; i < numSamples; ++i) {
            float sample = input[i] / 32768.0f;

            // Process combs in parallel
            float combSum = 0.0f;
            for (auto& comb : combs) {
                combSum += comb->process(sample);
            }

            // Process allpasses in series
            float apOut = combSum;
            for (auto& ap : allPasses) {
                apOut = ap->process(apOut);
            }

            // Mix dry and wet
            float outSample = (sample * dry) + (apOut * wet);
            outSample = fmax(-1.0f, fmin(outSample, 1.0f));

            output[i] = static_cast<short>(outSample * 32767.0f);
        }
    }

private:
    CombFilter* combs[4];
    AllPassFilter* allPasses[2];
};

extern "C" JNIEXPORT jlong JNICALL
Java_com_example_ReverbProcessor_initNativeReverb(JNIEnv* env, jobject thiz) {
    return reinterpret_cast<jlong>(new ReverbEffect(44100));
}

extern "C" JNIEXPORT jshortArray JNICALL
Java_com_example_ReverbProcessor_processNativeReverb(JNIEnv* env, jobject thiz, jlong handle, jshortArray input) {
    auto* reverb = reinterpret_cast<ReverbEffect*>(handle);
    jsize length = env->GetArrayLength(input);
    jshortArray output = env->NewShortArray(length);

    jshort* inputPtr = env->GetShortArrayElements(input, nullptr);
    jshort* outputPtr = new jshort[length];

    reverb->process(inputPtr, outputPtr, length);

    env->ReleaseShortArrayElements(input, inputPtr, 0);
    env->SetShortArrayRegion(output, 0, length, outputPtr);
    delete[] outputPtr;

    return output;
}

extern "C" JNIEXPORT void JNICALL
Java_com_example_ReverbProcessor_releaseNativeReverb(JNIEnv* env, jobject thiz, jlong handle) {
    delete reinterpret_cast<ReverbEffect*>(handle);
}
```

