Here's a Kotlin implementation for a local VPN service that filters packets by destination IP address:

```kotlin
// LocalVPNService.kt
import android.net.VpnService
import android.os.ParcelFileDescriptor
import java.io.FileInputStream
import java.io.FileOutputStream
import java.nio.ByteBuffer
import kotlin.concurrent.thread

class LocalVPNService : VpnService() {

    private var vpnInterface: ParcelFileDescriptor? = null
    private val blockedIPs = setOf("8.8.8.8") // Example blocked IPs

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        // Start VPN connection
        startVPN()
        return START_STICKY
    }

    private fun startVPN() {
        val builder = Builder()
            .setSession("LocalVPN")
            .addAddress("192.168.0.1", 24)
            .addDnsServer("8.8.8.8")
            .addRoute("0.0.0.0", 0)
            .setMtu(1500)

        vpnInterface = builder.establish()

        // Start packet processing
        thread {
            val inputStream = FileInputStream(vpnInterface?.fileDescriptor)
            val outputStream = FileOutputStream(vpnInterface?.fileDescriptor)

            val buffer = ByteBuffer.allocate(32767)
            while (true) {
                val length = inputStream.read(buffer.array())
                if (length > 0) {
                    if (!isBlocked(buffer)) {
                        // Forward non-blocked packets
                        outputStream.write(buffer.array(), 0, length)
                    }
                    buffer.clear()
                }
            }
        }
    }

    private fun isBlocked(buffer: ByteBuffer): Boolean {
        try {
            val version = buffer.get(0).toInt() shr 4
            return when (version) {
                4 -> {
                    // IPv4 - destination address starts at offset 16
                    val destIp = String.format(
                        "%d.%d.%d.%d",
                        buffer.get(16) and 0xff,
                        buffer.get(17) and 0xff,
                        buffer.get(18) and 0xff,
                        buffer.get(19) and 0xff
                    )
                    blockedIPs.contains(destIp)
                }
                6 -> {
                    // IPv6 - destination address starts at offset 24
                    val destIp = buildString {
                        for (i in 24 until 40 step 2) {
                            append("%02x%02x:".format(buffer.get(i).toInt(), buffer.get(i + 1).toInt()))
                        }
                    }.removeSuffix(":")
                    blockedIPs.contains(destIp)
                }
                else -> false
            }
        } catch (e: Exception) {
            return false
        }
    }

    override fun onDestroy() {
        vpnInterface?.close()
        super.onDestroy()
    }
}
```

