<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    public function add(string $name): void
    {
        $user = Auth::user();

        if ($user) {
            // Add to database, ensuring no duplicates
            $user->favorites()->firstOrCreate(['name' => $name]);
        } else {
            // Add to session
            $favorites = Session::get('favorites', []);
            if (!in_array($name, $favorites)) {
                $favorites[] = $name;
                Session::put('favorites', $favorites);
            }
        }
    }

    public function remove(string $name): void
    {
        $user = Auth::user();

        if ($user) {
            // Remove from database
            $user->favorites()->where('name', $name)->delete();
        } else {
            // Remove from session
            $favorites = Session::get('favorites', []);
            $favorites = array_diff($favorites, [$name]);
            Session::put('favorites', $favorites);
        }
    }

    public function get(): array
    {
        $user = Auth::user();

        if ($user) {
            // Retrieve from database
            return $user->favorites()->pluck('name')->toArray();
        }

        // Retrieve from session
        return Session::get('favorites', []);
    }

    public function has(string $name): bool
    {
        $user = Auth::user();

        if ($user) ;
            // Check database
            return $user->favorites()->where('name', $name)->exists();
        }

        // Check session
