Here's a smart contract implementing an ERC-1155 "Creds" token with transfer restrictions and role-based management:

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract CredsToken is ERC1155, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");

    uint256 public constant CREDS_TOKEN_ID = 1;

    constructor(string memory uri)
        ERC1155(uri)
    {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(BURNER_ROLE, msg.sender);
    }

    // Mint CREDS tokens to specified address
    function mintCreds(address to, uint256 amount) 
        public 
        onlyRole(MINTER_ROLE) 
    {
        _mint(to, CREDS_TOKEN_ID, amount, "");
    }

    // Admin burn function (burn from any address)
    function adminBurn(address from, uint256 amount) 
        public 
        onlyRole(BURNER_ROLE) 
    {
        _burn(from, CREDS_TOKEN_ID, amount);
    }

    // Set new URI for all token types
    function setURI(string memory newuri) 
        public 
        onlyRole(DEFAULT_ADMIN_ROLE) 
    {
        _setURI(newuri);
    }

    // Override to prevent CREDS transfers
    function _beforeTokenTransfer(
        address operator,
        address from,
        address to,
        uint256[] memory ids,
        uint256[] memory amounts,
        bytes memory data
    ) internal virtual override {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);

        for (uint256 i = 0; i < ids.length; i++) {
            if (ids[i] == CREDS_TOKEN_ID) {
                require(
                    from == address(0) || to == address(0),
                    "CredsToken: CREDS transfers are disabled"
                );
            }
        }
    }

    // Support interfaces
    function supportsInterface(bytes4 interfaceId)
        public
        view
        virtual
        override(ERC1155, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}
```

Key Features:

1. **Role-Based Access Control**:
   - `DEFAULT_ADMIN_ROLE`: Can manage roles and update metadata URI
   - `MINTER_ROLE`: Can mint new CREDS tokens
   - `BURNER_ROLE`: Can burn CREDS tokens from any account

2. **Transfer Restrictions**:
   - CREDS tokens (ID = 1) cannot be transferred between accounts
   - Only allowed operations are minting (creating new tokens) and burning (destroying tokens)

3. **Management Functions**:
   - `mintCreds()`: Create new CREDS tokens for specified account
   - `adminBurn()`: Remove CREDS tokens from any account
   - `setURI()`: Update metadata URI (supports off-chain metadata)

4. **ERC-1155 Compliance**:
   - Maintains compatibility with standard ERC-1155 functionality
   - Supports interface detection
   - Allows for potential expansion with other token types

Usage Patterns:

1. Deploy with initial metadata URI
2. Admin assigns MINTER/BURNER roles to appropriate addresses
3. Authorized minters can issue CREDS to users
4. CREDS represent non-transferable credentials/reputation
5. Authorized burners can remove CREDS when needed
6. Metadata can be updated to reflect credential changes

To use this contract:

1. Deploy with an initial metadata URI (e.g., "https://example.com/api/token/{id}")
2. Grant MINTER_ROLE to addresses that need to issue credentials
3. Grant BURNER_ROLE to addresses that need to revoke credentials
4. Users can check CREDS balance with `balanceOf(address, CREDS_TOKEN_ID)`

This implementation provides a flexible foundation for non-transferable credential management while maintaining compatibility with the ERC-1155 ecosystem.

To parse a TCP segment from an IPv4 packet's payload in TypeScript, you can use the following implementation. This code extracts TCP header fields, options, and payload from a `Uint8Array` containing the TCP segment:

```typescript
interface TcpPacket {
  srcPort: number;
  destPort: number;
  seqNum: number;
  ackNum: number;
  dataOffset: number;
  flags: {
    ns: number;
    cwr: number;
    ece: number;
    urg: number;
    ack: number;
    psh: number;
    rst: number;
    syn: number;
    fin: number;
  };
  windowSize: number;
  checksum: number;
  urgentPointer: number;
  options: Uint8Array;
  payload: Uint8Array;
}

function parseTcpPacket(data: Uint8Array): TcpPacket {
  if (data.length < 20) {
    throw new Error('TCP packet is too short');
  }

  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  let offset = 0;

  // Read first 12 bytes of fixed header
  const srcPort = view.getUint16(offset); offset += 2;
  const destPort = view.getUint16(offset); offset += 2;
  const seqNum = view.getUint32(offset); offset += 4;
  const ackNum = view.getUint32(offset); offset += 4;

  // Parse header length and flags
  const dataOffsetAndFlags = view.getUint16(offset);
  const dataOffset = (dataOffsetAndFlags >> 12) & 0x0F;
  const headerLength = dataOffset * 4;
  offset += 2;

  // Validate header length
  if (dataOffset < 5) throw new Error(`Invalid TCP data offset: ${dataOffset}`);
  if (data.length < headerLength) throw new Error('TCP header exceeds data length');

  // Extract flags
  const flags = dataOffsetAndFlags & 0x1FF;
  const ns = (flags >> 8) & 1;
  const cwr = (flags >> 7) & 1;
  const ece = (flags >> 6) & 1;
  const urg = (flags >> 5) & 1;
  const ack = (flags >> 4) & 1;
  const psh = (flags >> 3) & 1;
  const rst = (flags >> 2) & 1;
  const syn = (flags >> 1) & 1;
  const fin = (flags >> 0) & 1;

  // Remaining header fields
  const windowSize = view.getUint16(offset); offset += 2;
  const checksum = view.getUint16(offset); offset += 2;
  const urgentPointer = view.getUint16(offset); offset += 2;

  // Extract options and payload
  const options = data.subarray(20, headerLength);
  const payload = data.subarray(headerLength);

  return {
    srcPort,
    destPort,
    seqNum,
    ackNum,
    dataOffset: headerLength,
    flags: { ns, cwr, ece, urg, ack, psh, rst, syn, fin },
    windowSize,
    checksum,
    urgentPointer,
    options,
    payload
  };
}
```

**Usage Example:**
```typescript
// Assuming `ipv4Payload` is your Uint8Array from the IPv4 packet
try {
  const tcpSegment = parseTcpPacket(ipv4Payload);
  console.log('Source Port:', tcpSegment.srcPort);
  console.log('Destination Port:', tcpSegment.destPort);
  console.log('SYN Flag:', tcpSegment.flags.syn);
  console.log('Payload Length:', tcpSegment.payload.length);
} catch (error) {
  console.error('Error parsing TCP segment:', error);
}
```

**Key Notes:**
1. **Header Validation:** Checks for minimum header length and valid data offset.
2. **Network Byte Order:** Uses `DataView` with big-endian format (network byte order).
3. **Flags Extraction:** Properly extracts all 9 TCP flags using bitwise operations.
4. **Options Handling:** Correctly slices the options portion based on header length.
5. **Error Handling:** Includes basic error checking for invalid packets.

This implementation focuses on parsing TCP segments from an existing byte array. Implementing full TCP protocol functionality (like handshakes, retransmissions, and flow control) would require significantly more code and state management.

