import React, { useState, useEffect } from 'react';
import axios from 'axios';

const TodoList = () => {
  const [todos, setTodos] = useState([]);
  const [description, setDescription] = useState('');

  useEffect(() => {
    fetchTodos();
  }, []);

  const fetchTodos = async () => {
    const response = await axios.get('/todos');
    setTodos(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!description) return;
    await axios.post('/todos', { description });
    setDescription('');
    fetchTodos();
  };

  const updateTodo = async (id, currentDescription, currentCompleted) => {
    await axios.put(`/todos/${id}`, {
      description: currentDescription,
      completed: !currentCompleted
    });
    fetchTodos();
  };

  const deleteTodo = async (id) => {
    await axios.delete(`/todos/${id}`);
    fetchTodos();
  };

  return (
    <div className="container">
      <h1>PERN Todo List</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Enter todo"
        />
        <button type="submit">Add Todo</button>
      </form>
      <ul>
        {todos.map(todo => (
          <li key={todo.todo_id}>
            <span
              style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}
            >
              {todo.description}
            </span>
            <div>
              <button onClick={() => updateTodo(todo.todo_id, todo.description, todo.completed)}>
                {todo.completed ? 'Undo' : 'Complete'}
              </button>
              <button onClick={() => deleteTodo(todo.todo_id)}>Delete</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default TodoList;
```

