```cpp
#include <ap_fixed.h>
#include <hls_math.h>

// Define fixed-point data type (16-bit total, 8 integer bits)
typedef ap_fixed<16,8> fixed_type;

// Top-level function with interface pragmas
void mnist_nn(
    const fixed_type input[784],
    fixed_type prediction[10]
) {
    #pragma HLS INTERFACE mode=bram port=input
    #pragma HLS INTERFACE mode=bram port=prediction
    #pragma HLS INTERFACE mode=ap_ctrl_none port=return

    // Layer 1 parameters (pretrained weights/biases)
    static const fixed_type weights1[784][128] = {
        // Pretrained weights would be initialized here
        // This array should be filled with actual trained values
    };
    #pragma HLS ARRAY_PARTITION variable=weights1 cyclic dim=2 factor=16

    static const fixed_type biases1[128] = {
        // Pretrained biases would be initialized here
    };
    #pragma HLS ARRAY_PARTITION variable=biases1 complete dim=1

    // Layer 2 parameters (pretrained weights/biases)
    static const fixed_type weights2[128][10] = {
        // Pretrained weights would be initialized here
    };
    #pragma HLS ARRAY_PARTITION variable=weights2 cyclic dim=2 factor=4

    static const fixed_type biases2[10] = {
        // Pretrained biases would be initialized here
    };
    #pragma HLS ARRAY_PARTITION variable=biases2 complete dim=1

    // Hidden layer storage
    fixed_type hidden[128];
    #pragma HLS ARRAY_PARTITION variable=hidden complete dim=1

    // Layer 1: Input -> Hidden with ReLU
    L1: for(int neuron = 0; neuron < 128; neuron++) {
        #pragma HLS PIPELINE II=1
        fixed_type acc = biases1[neuron];

        L1_MAC: for(int dim = 0; dim < 784; dim++) {
            acc += input[dim] * weights1[dim][neuron];
        }

        hidden[neuron] = (acc > 0) ? acc : fixed_type(0);
    }

    // Layer 2: Hidden -> Output
    fixed_type output[10];
    #pragma HLS ARRAY_PARTITION variable=output complete dim=1

    L2: for(int neuron = 0; neuron < 10; neuron++) {
        #pragma HLS PIPELINE II=1
        fixed_type acc = biases2[neuron];

        L2_MAC: for(int dim = 0; dim < 128; dim++) {
            acc += hidden[dim] * weights2[dim][neuron];
        }

        output[neuron] = acc;
    }

    // Softmax activation
    fixed_type exp_sum = 0;
    Softmax: for(int i = 0; i < 10; i++) {
        #pragma HLS PIPELINE II=1
        fixed_type exp_val = hls::exp(output[i]);
        prediction[i] = exp_val;
        exp_sum += exp_val;
    }

    // Normalize predictions
    Normalize: for(int i = 0; i < 10; i++) {
        #pragma HLS PIPELINE II=1
        prediction[i] /= exp_sum;
    }
}
```

