Here's a Rust implementation that generates an infinite stream of prime numbers using trial division for primality testing:

```rust
struct Primes {
    current: u64,
}

impl Primes {
    fn new() -> Self {
        Primes { current: 2 }
    }
}

impl Iterator for Primes {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let candidate = self.current;
            self.current += 1;
            if is_prime(candidate) {
                return Some(candidate);
            }
        }
    }
}

fn is_prime(n: u64) -> bool {
    if n <= 1 {
        return false;
    }
    if n <= 3 {
        return true;
    }
    if n % 2 == 0 || n % 3 == 0 {
        return false;
    }

    let sqrt_n = (n as f64).sqrt() as u64;
    let mut i = 5;
    let mut w = 2;

    while i <= sqrt_n {
        if n % i == 0 {
            return false;
        }
        i += w;
        w = 6 - w; // Alternate between 2 and 4 (5, 7, 11, 13, 17, ...)
    }
    true
}

fn main() {
    let primes = Primes::new();
    for prime in primes.take(20) {
        println!("{}", prime);
    }
}
```

