Here's a Rust program that reads URLs from a file, separates YouTube URLs, and downloads them using yt-dlp:

```rust
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};
use regex::Regex;
use std::process::Command;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Read command-line arguments
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <input_file>", args[0]);
        std::process::exit(1);
    }
    let filename = &args[1];

    // Compile YouTube URL regex pattern
    let youtube_re = Regex::new(r"^(https?://)?(www\.)?(youtube\.com|youtu\.be)/")?;

    // Read and classify URLs
    let file = File::open(filename)?;
    let reader = BufReader::new(file);
    let mut youtube_urls = Vec::new();
    let mut other_urls = Vec::new();

    for line in reader.lines() {
        let line = line?;
        let url = line.trim();
        if url.is_empty() {
            continue;
        }

        if youtube_re.is_match(url) {
            youtube_urls.push(url.to_string());
        } else {
            other_urls.push(url.to_string());
        }
    }

    // Print classified URLs
    println!("YouTube URLs ({}):", youtube_urls.len());
    for url in &youtube_urls {
        println!("{}", url);
    }

    println!("\nOther URLs ({}):", other_urls.len());
    for url in &other_urls {
        println!("{}", url);
    }

    // Download YouTube videos
    println!("\nDownloading YouTube videos...");
    for url in youtube_urls {
        println!("Downloading: {}", url);
        let status = Command::new("yt-dlp")
            .arg(&url)
            .status()?;

        if !status.success() {
            eprintln!("Warning: Failed to download {}", url);
        }
    }

    Ok(())
}
```

