Here's a C# program that sends a POST request with a client certificate attached:

```csharp
using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        // Configuration variables
        string url = "https://example.com/api/endpoint";
        string certificatePath = "path/to/your/certificate.pfx";
        string certificatePassword = "your-certificate-password";
        string jsonContent = "{\"key\": \"value\"}";

        try
        {
            // Load the client certificate
            X509Certificate2 clientCertificate = new X509Certificate2(
                certificatePath, 
                certificatePassword,
                X509KeyStorageFlags.PersistKeySet | X509KeyStorageFlags.Exportable
            );

            // Configure the HTTP handler with the certificate
            var handler = new HttpClientHandler();
            handler.ClientCertificates.Add(clientCertificate);

            // WARNING: Only use this for testing! Bypassing SSL verification is insecure.
            // If you need valid SSL verification, remove this line.
            handler.ServerCertificateCustomValidationCallback = 
                HttpClientHandler.DangerousAcceptAnyServerCertificateValidator;

            // Create HTTP client with the handler
            using (var httpClient = new HttpClient(handler))
            {
                // Create POST content
                var content = new StringContent(jsonContent, Encoding.UTF8, "application/json");

                // Send POST request
                HttpResponseMessage response = await httpClient.PostAsync(url, content);

                // Handle response
                if (response.IsSuccessStatusCode)
                {
                    string responseBody = await response.Content.ReadAsStringAsync();
                    Console.WriteLine($"Success: {responseBody}");
                }
                else
                {
                    Console.WriteLine($"Error: {response.StatusCode} - {response.ReasonPhrase}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Exception: {ex.Message}");
        }
    }
}
```

